"""Veo avatar agent: YOUR talking part of every Short is generated by Google Veo (Gemini API).

What it does, for every Short:
1. Finds the lines where you are on screen (HOOK / PROBLEM / RESULT / CTA ... everything that is not a Zoho
   screen), using the same timing the composer uses.
2. For each of those lines it asks Veo to animate your photo (the photo rotation stays the same): you look into
   the camera and SAY that exact line - real lip movement, blinking, head and hand movement.
   All clips are requested in parallel, so a Short takes ~2-6 min of Veo time.
3. Veo's own audio is thrown away. Your normal AI voice (Gemini TTS) stays the voice of the whole Short.
   Whisper listens to each Veo clip, finds when every word is said, and the clip is re-timed word by word so
   the lips land on the TTS voice.
4. Returns ONE avatar video as long as the voice track, so composer.py works exactly as before
   (screens, captions, music, layout: nothing else changes).

Key: VEO_API_KEY secret only (a billing-enabled Gemini API key; Veo has no free tier). No VEO_API_KEY -> Veo is
skipped and nothing is charged (the normal GEMINI_API_KEY is never used for Veo).
If anything fails, avatar.py falls back to SadTalker and then to the photo, as before.
"""
import json
import os
import shutil
import subprocess
import time
from pathlib import Path

from PIL import Image

from .config import CH

_V = (CH.get("avatar", {}) or {}).get("veo", {}) or {}
MODELS = [m.strip() for m in (os.getenv("VEO_MODELS") or ",".join(_V.get("models") or [
    "veo-3.1-fast-generate-preview", "veo-3.1-lite-generate-preview", "veo-3.1-generate-preview"])).split(",")
    if m.strip()]
RESOLUTION = str(_V.get("resolution", "720p"))
MAX_SECONDS = float(_V.get("max_seconds_per_short", 48))   # cost guard: Veo seconds per Short
MAX_PIECE = 7.2                                            # longest line piece sent to one 8 s clip
SCENE = (_V.get("scene") or "").strip()
VOICE_HINT = (_V.get("speech") or "friendly, confident Hinglish explainer voice, Indian accent, natural pace").strip()
POLL_TIMEOUT = 15 * 60
FPS = 30


def _client():
    from google import genai
    key = (os.getenv("VEO_API_KEY") or "").strip()
    if not key:
        raise RuntimeError("VEO_API_KEY secret not set - Veo skipped (free SadTalker is used instead)")
    return genai.Client(api_key=key)


def _run(cmd, **kw):
    return subprocess.run(cmd, check=True, **kw)


def _dur(p):
    return float(subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0",
                                 str(p)], capture_output=True, text=True, check=True).stdout.strip())


# ------------------------------------------------------------------ which parts are "you"
def pieces(lines, words, dur):
    """[{t0, t1, text, words}] - every on-camera line (long lines split so each fits one 8 s clip)."""
    from .composer import _clean, _is_screen, line_times
    times = line_times(lines, words, dur)
    out, k = [], 0
    for l, (a, b) in zip(lines, times):
        text = _clean(l.get("say") or l.get("tts"))
        n = len(text.split())
        lw = list(words[k:k + n])
        k += n
        if _is_screen(l) or not lw:
            continue
        groups, cur = [], []
        for w in lw:
            if cur and w[1] - (cur[0][0] if groups else a) > MAX_PIECE:
                groups.append(cur)
                cur = []
            cur.append(w)
        groups.append(cur)
        for gi, g in enumerate(groups):
            t0 = a if gi == 0 else g[0][0]
            t1 = b if gi == len(groups) - 1 else groups[gi + 1][0][0]
            out.append({"t0": t0, "t1": max(t1, t0 + 0.3), "text": " ".join(w[2] for w in g), "words": g})
    return out


def _clip_seconds(span):
    for d in (4, 6, 8):
        if span + 0.8 <= d:
            return d
    return 8


# ------------------------------------------------------------------ first frame
def first_frame(photo, out):
    """Your photo cropped to Veo's 9:16 / 16:9 frame (head kept in the upper third). Returns (path, aspect)."""
    im = Image.open(photo).convert("RGB")
    portrait = im.height >= im.width
    aspect, (tw, th) = ("9:16", (720, 1280)) if portrait else ("16:9", (1280, 720))
    r = tw / th
    if im.width / im.height > r:                                  # too wide -> cut the sides
        nw = int(im.height * r)
        im = im.crop(((im.width - nw) // 2, 0, (im.width - nw) // 2 + nw, im.height))
    else:                                                         # too tall -> cut mostly from the bottom
        nh = int(im.width / r)
        top = int((im.height - nh) * 0.25)
        im = im.crop((0, top, im.width, top + nh))
    im = im.resize((tw, th), Image.LANCZOS)
    im.save(out, quality=95)
    return out, aspect


def _prompt(text):
    return (f"The man in this photo looks straight into the camera and talks to the viewer like a YouTube "
            f"explainer ({VOICE_HINT}). He says, in Hinglish: \"{text}\" "
            "Clear, natural lip movement that matches every word, natural blinking, small head nods and relaxed "
            "hand gestures. Same face, hair, beard, clothes and background as the photo. Static camera, medium "
            "close-up, face sharp and well lit the whole time. He starts speaking immediately and keeps talking "
            "until the very end. Audio: only his voice, no music. No subtitles, no captions, no text on screen."
            + (f" {SCENE}" if SCENE else ""))


# ------------------------------------------------------------------ Veo calls (parallel)
def _submit(client, img_bytes, aspect, text, seconds, model):
    from google.genai import types
    return client.models.generate_videos(
        model=model, prompt=_prompt(text),
        image=types.Image(image_bytes=img_bytes, mime_type="image/jpeg"),
        config=types.GenerateVideosConfig(aspect_ratio=aspect, duration_seconds=seconds, resolution=RESOLUTION,
                                          person_generation="allow_adult", number_of_videos=1))


def _save(client, gen, path):
    try:
        client.files.download(file=gen.video, destination=str(path))
    except TypeError:                                             # older google-genai without destination=
        client.files.download(file=gen.video)
        gen.video.save(str(path))
    if not path.exists() or path.stat().st_size < 10_000:
        if getattr(gen.video, "video_bytes", None):
            path.write_bytes(gen.video.video_bytes)
    if not path.exists() or path.stat().st_size < 10_000:
        raise RuntimeError("downloaded Veo clip is empty")


def generate(img, aspect, jobs, workdir: Path):
    """jobs: [{text, seconds}] -> list of clip paths (same order). Retries on the next model."""
    client = _client()
    img_bytes = Path(img).read_bytes()
    state = [{"try": 0, "op": None, "model": None, "done": False, "err": None} for _ in jobs]

    def start(i):
        s = state[i]
        while s["try"] < len(MODELS) * 2:
            model = MODELS[s["try"] % len(MODELS)]
            s["try"] += 1
            try:
                s["op"], s["model"] = _submit(client, img_bytes, aspect, jobs[i]["text"], jobs[i]["seconds"], model), model
                print(f"[veo] clip {i + 1}/{len(jobs)} started on {model} ({jobs[i]['seconds']}s)")
                return True
            except Exception as e:
                s["err"] = e
                print(f"[veo] clip {i + 1} start on {model} failed: {str(e)[:200]}")
                time.sleep(min(30, 5 * s["try"]))
        return False

    for i in range(len(jobs)):
        if not start(i):
            raise RuntimeError(f"Veo could not start clip {i + 1}: {str(state[i]['err'])[:200]}")
        time.sleep(1)

    out = [workdir / f"veo_{i:02d}.mp4" for i in range(len(jobs))]
    t_end = time.time() + POLL_TIMEOUT
    while not all(s["done"] for s in state):
        if time.time() > t_end:
            raise RuntimeError("Veo timed out")
        time.sleep(10)
        for i, s in enumerate(state):
            if s["done"]:
                continue
            try:
                s["op"] = client.operations.get(s["op"])
            except Exception as e:
                print(f"[veo] poll clip {i + 1}: {str(e)[:150]}")
                continue
            if not s["op"].done:
                continue
            resp = getattr(s["op"], "response", None) or getattr(s["op"], "result", None)
            vids = getattr(resp, "generated_videos", None) or []
            if s["op"].error or not vids:
                why = s["op"].error or getattr(resp, "rai_media_filtered_reasons", None) or "no video returned"
                print(f"[veo] clip {i + 1} failed on {s['model']}: {str(why)[:200]}")
                if not start(i):
                    raise RuntimeError(f"Veo failed clip {i + 1}: {str(why)[:200]}")
                continue
            _save(client, vids[0], out[i])
            s["done"] = True
            print(f"[veo] clip {i + 1}/{len(jobs)} ready ({_dur(out[i]):.1f}s, {s['model']})")
    return out


# ------------------------------------------------------------------ lip timing: Veo speech -> TTS voice
def _anchors(piece, clip, workdir: Path):
    """[(tts_time, clip_time)] pairs: the same script word in the TTS voice and in the Veo clip."""
    from .editor import align_to_script, transcribe
    cdur = _dur(clip)
    tw = piece["words"]
    if piece.get("reuse"):          # clip made for another line: just keep the talking motion going
        return [(piece["t0"], 0.15), (piece["t1"], max(min(cdur - 0.25, 0.15 + piece["t1"] - piece["t0"]), 0.5))]
    try:
        vw = align_to_script(transcribe(clip, workdir), piece["text"])
    except Exception as e:
        print(f"[veo] whisper on clip failed: {str(e)[:150]}")
        vw = []
    if len(vw) != len(tw) or not vw:
        # no usable words: map the whole line linearly onto the clip (minus the edges)
        return [(piece["t0"], 0.15), (piece["t1"], max(cdur - 0.25, 0.5))]
    lead = max(tw[0][0] - piece["t0"], 0.0)
    tail = max(piece["t1"] - tw[-1][1], 0.0)
    pts = [(piece["t0"], max(vw[0][0] - lead, 0.0))]
    for (ts, _, _), (vs, _, _) in zip(tw, vw):
        if ts - pts[-1][0] >= 0.45 and vs - pts[-1][1] >= 0.15:
            pts.append((ts, vs))
    pts.append((piece["t1"], min(vw[-1][1] + tail, cdur - 0.04)))
    # keep it smooth: monotonic, and never faster than 2.2x or slower than 0.45x
    clean = [pts[0]]
    for t, v in pts[1:]:
        dt, dv = t - clean[-1][0], v - clean[-1][1]
        if dt <= 0:
            continue
        if 0.45 <= dv / dt <= 2.2 or (t, v) == pts[-1]:
            clean.append((t, max(v, clean[-1][1] + 0.01)))
    return clean


def _interp(t, pts):
    if t <= pts[0][0]:
        return pts[0][1]
    for (t0, v0), (t1, v1) in zip(pts, pts[1:]):
        if t <= t1:
            return v0 + (v1 - v0) * (t - t0) / max(t1 - t0, 1e-6)
    return pts[-1][1]


def _frames(clip, d: Path, size):
    d.mkdir(parents=True, exist_ok=True)
    w, h = size
    _run(["ffmpeg", "-y", "-loglevel", "error", "-i", str(clip), "-vf",
          f"scale={w}:{h}:force_original_aspect_ratio=increase,crop={w}:{h},setsar=1",
          "-q:v", "2", str(d / "%05d.jpg")])
    fr = sorted(d.glob("*.jpg"))
    if not fr:
        raise RuntimeError(f"no frames in {clip}")
    return fr, len(fr) / max(_dur(clip), 0.1)


def assemble(photo_frame, plist, clips, dur, workdir: Path, out: Path):
    """One continuous avatar video (length = voice). Your lines = re-timed Veo clips, the rest = photo."""
    w, h = Image.open(photo_frame).size
    seq = workdir / "seq"
    shutil.rmtree(seq, ignore_errors=True)
    seq.mkdir(parents=True)
    still = workdir / "still.jpg"
    Image.open(photo_frame).convert("RGB").save(still, quality=95)
    maps, cache = [], {}
    for i, (p, c) in enumerate(zip(plist, clips)):
        if str(c) not in cache:     # the same clip can serve several lines (manual Gemini mode)
            cache[str(c)] = _frames(c, workdir / f"f{len(cache):02d}", (w, h))
        fr, sfps = cache[str(c)]
        pts = _anchors(p, c, workdir / f"w{i:02d}")
        maps.append((p, fr, sfps, pts))
        print(f"[veo] clip {i + 1}: {len(pts)} lip anchors for {p['t1'] - p['t0']:.1f}s line")
    n = int(round(dur * FPS)) + 1
    for k in range(n):
        t = k / FPS
        src = still
        for p, fr, sfps, pts in maps:
            if p["t0"] <= t < p["t1"]:
                src = fr[min(max(int(round(_interp(t, pts) * sfps)), 0), len(fr) - 1)]
                break
        os.symlink(src.resolve(), seq / f"{k:06d}.jpg")
    _run(["ffmpeg", "-y", "-loglevel", "error", "-framerate", str(FPS), "-i", str(seq / "%06d.jpg"),
          "-vf", "format=yuv420p", "-c:v", "libx264", "-preset", "veryfast", "-crf", "15", "-an", str(out)])
    shutil.rmtree(seq, ignore_errors=True)
    for i in range(len(cache)):
        shutil.rmtree(workdir / f"f{i:02d}", ignore_errors=True)
    return out


def make(photo, lines, words, dur, workdir: Path):
    """Your talking avatar from Veo, timed to the voice. Returns the avatar mp4 (same length as the voice)."""
    workdir.mkdir(parents=True, exist_ok=True)
    plist = pieces(lines, words, dur)
    if not plist:
        raise RuntimeError("no on-camera lines in this script")
    jobs = [{"text": p["text"], "seconds": _clip_seconds(p["t1"] - p["t0"])} for p in plist]
    total = sum(j["seconds"] for j in jobs)
    if total > MAX_SECONDS:
        raise RuntimeError(f"Veo would need {total}s (> {MAX_SECONDS:.0f}s limit in channel.yaml)")
    frame, aspect = first_frame(photo, workdir / "first_frame.jpg")
    print(f"[veo] {len(jobs)} clips, {total}s of Veo, aspect {aspect}, models {MODELS}")
    clips = generate(frame, aspect, jobs, workdir)
    out = assemble(frame, plist, clips, dur, workdir, workdir / "avatar_veo.mp4")
    (workdir / "veo.json").write_text(json.dumps({"pieces": [{k: v for k, v in p.items() if k != "words"}
                                                              for p in plist], "jobs": jobs}, ensure_ascii=False,
                                                 indent=1), encoding="utf-8")
    print(f"[veo] avatar ready: {out}")
    return out
